 NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.paralympic.org/sites/default/files/2020-11/IPC%20Accessibility%20Guide%20-%204th%20edition%20-%20October%202020_0.pdf', '2026-09-17', NULL, NULL, 4, 'standard_eb', 'INT', NULL, NULL, NULL, 'COMPLETE', 'VERIFIED', 'NO-MATCH', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-17 21:38', 'session_2026-09-17-research-batch-11-threshold-legs-bcd', '2026-09-17 21:38', 'session_2026-09-17-research-batch-11-threshold-legs-bcd', 'retrieval-log', NULL, 1, NULL, 'Section 2.1 Key Measurement Reference Table, p.27; Ramp definition p.24', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'international', 'captured', 'pending', NULL, NULL, NULL, NULL, 'CLOSED', 'tool', NULL);
INSERT INTO "evidence_sources" ("ref_id", "source_type", "author_count", "author_count_is_complete", "first_author_last", "first_author_first", "is_corporate_primary", "author_display", "pub_year", "pub_year_note", "pub_title", "pub_subtitle", "chapter_title", "original_title", "lang_detected", "lang_detection_method", "pub_title_en", "pub_subtitle_en", "chapter_title_en", "journal_name_en", "translation_method", "translation_reviewed", "journal_name", "journal_abbrev", "volume", "issue", "pages_start", "pages_end", "article_number", "publisher", "publisher_location", "edition", "book_title", "series", "series_number", "report_number", "institution", "standard_number", "doi", "pmid", "pmcid", "isbn", "issn", "url", "url_accessed", "handle", "local_id", "tier", "evidence_type", "jurisdiction", "co1_provenance", "co1_source_type", "synthesis_attribution_required", "metadata_quality", "verification_status", "doi_resolution_outcome", "bpc_shorthand", "bpc_note", "grey_flag", "grey_reason", "verification_note", "prior_expectation", "search_queries_used", "derivation_chain", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "verified_by_tool", "last_verified_at", "verification_attempt_count", "superseded_by_ref_id", "pages", "pub_month", "language", "subtype", "citation_count", "url_resolution_outcome", "url_last_fetched", "url_match_similarity", "metadata_integrity_status", "metadata_integrity_detail", "code_currency_status", "code_currency_verified_at", "code_currency_verified_by_session", "code_currency_notes", "scope", "data_capture_status", "citation_mining_status", "processing_blocked_reason", "standard_number_note", "author_display_note", "publisher_note", "verification_disposition", "verification_method", "verification_closure_reason") VALUES ('REF-00995', NULL, NULL, 0, NULL, NULL, 0, NULL, 2009, NULL, 'Besluit van de Vlaamse Regering van 5 juni 2009 tot vaststelling van een gewestelijke stedenbouwkundige verordening betreffende toegankelijkheid (artikel 19, versie in werking vanaf 31/03/2011)', NULL, NULL, NULL, 'nl', NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://codex.vlaanderen.be/portals/codex/documenten/1018282.html', '2026-09-17', NULL, NULL, 6, 'code', 'BE', NULL, NULL, NULL, 'COMPLETE-STATUTORY', 'VERIFIED', NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-17 21:43', 'session_2026-09-17-research-batch-11-threshold-legs-bcd', '2026-09-17 21:43', 'session_2026-09-17-research-batch-11-threshold-legs-bcd', 'retrieval-log', NULL, 1, NULL, 'Artikel 19 §1 (1°–4°)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'intrinsic', 'captured', 'pending', NULL, NULL, NULL, NULL, 'CLOSED', 'tool', NULL);
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation") VALUES (47, 'accessible-circulation-geometry', 'US', 'en', 1, 'co1', 'intrinsic', 'Paralyzed Veterans of America accessible design ramp slope publication pva.org', NULL, 'web', 'scoping', NULL, 9, 9, 0, NULL, NULL, NULL, 0, 'session_2026-09-17-research-batch-11-threshold-legs-bcd', '2026-09-17 21:35', 'PRIOR FALSIFIED, AND THE WAY IT FAILED IS THE FINDING. PVA does not restate 1:12; it publishes NO ramp gradient guidance on its free web surface at all. Three pages retrieved and persisted (accessible-design index 4bac88bf, expert-services 0957e92f, image-guide from the same pass), all HTTP 200. Across all three: ramp 0, slope 0, gradient 0, incline 0, 1:12 0. The image-guide page appears to contain 62 instances of gradient; ALL are WordPress CSS presets (linear-gradient, --wp--preset--gradient--*), verified by inspecting every occurrence rather than trusting the count — exactly the false positive that would have produced a fabricated admission. R14 DIAGNOSIS IS TWO-PART AND BOTH PARTS MATTER: (a) GENUINE ABSENCE from the free surface — the query was well formed and reached PVA own accessible-design section, so this is not wrong index or query shape; (b) RETRIEVAL FAILURE for the substantive carrier — PVA design knowledge is in Accessible Home Design, 2nd Edition, sold on Amazon, and in a consultancy service staffed by its own architects. THE STRUCTURAL FINDING FOR THIS PROJECT: a major disabled-led organisation with on-staff architects keeps its design expertise behind a book sale and a service, so its Co-1 authority on this parameter is unreachable by the route this corpus uses. That is a reason Co-1 gradient evidence is scarce, and it is not the same thing as disabled people having no position on gradient.', 0, 'Batch 09 logged this as zero-yield from a general query; batch 10 never re-ran it at source. PVA publishes accessibility design guidance and is a disabled-led membership organisation, so a zero FROM ITS OWN SITE is a far stronger claim than a zero from a search engine. Prediction: PVA does publish ramp guidance, and it restates the ADA 1:12 rather than contesting it — a Co-1 organisation reproducing the regulatory floor rather than judging it. Falsified if PVA states a preferred gradient of its own with a warrant.');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation") VALUES (48, 'accessible-circulation-geometry', 'FR', 'fr', 1, 'co1', 'intrinsic', 'APF France Handicap accessibilité pente rampe position dossier site apf-francehandicap.org', NULL, 'web', 'scoping', NULL, 9, 9, 0, NULL, NULL, NULL, 0, 'session_2026-09-17-research-batch-11-threshold-legs-bcd', '2026-09-17 21:36', 'PRIOR CONFIRMED ON THE SUBSTANCE, WRONG ON THE MECHANISM. Right: APF publishes at the level of rights and enforcement, not design specification. Wrong: it is not a retrieval failure — both pages retrieved cleanly at HTTP 200 (Occitanie conception-des-lieux 82cb2adc, national policy position e689d032). The content simply is not about gradient. Across both: pente 0, rampe 0, plan incliné 0. The only numbers are Ifop/APF 2020 survey statistics (9 in 10 experience accessibility difficulties in travel; 72 percent of people with pushchairs; 65 percent of non-disabled people dissatisfied with street accessibility) and an 87 percent web-accessibility conformance score in the footer — every one inspected individually rather than trusted from a count, because a bare 5 % in a French accessibility page is exactly what a careless pass would file as a gradient. R14 DIAGNOSIS: GENUINE ABSENCE on the surface reached, query well formed and on-site. NOT wrong index: the query named the domain and returned APF own pages. FRANCE NOW HAS NEITHER ROUTE — Légifrance blocks the statutory text (batch 10, lead 86) and the national DPO does not publish the figure. Those survey statistics are real evidence of something and belong to a different parameter; not filed here, and deliberately not stretched to fit this one.', 0, 'Batch 09 got vendors and compliance consultancies from a general query. Going at the publication site directly is the change. I expect position material framed on rights and enforcement rather than on a gradient, and a real chance of RETRIEVAL FAILURE behind site navigation rather than absence. Falsified if APF states a gradient position — which would also give France a Co-1 route after Légifrance blocked the statutory one.');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation") VALUES (49, 'accessible-circulation-geometry', 'INT', 'en', 4, 'standard_eb', 'international', 'IPC Accessibility Guide International Paralympic Committee ramp gradient technical requirements PDF', NULL, 'web', 'scoping', NULL, 9, 9, 1, NULL, NULL, NULL, 0, 'session_2026-09-17-research-batch-11-threshold-legs-bcd', '2026-09-17 21:39', 'PRIOR CONFIRMED ON ALL THREE CLAUSES, AND THE MARGIN IS LARGER THAN EXPECTED. Freely published: 216-page PDF straight off paralympic.org, HTTP 200, 5,066,628 bytes persisted. States a gradient: Section 2.1 Key Measurement Reference Table, p.27. Shallower than 1:12: best practice is 1:20 (5%) against the ADA and Japanese mandatory 1:12 (8.33%) — a factor of 1.67 on the same parameter — with 1:14 (7.14%) accepted only for secondary or ancillary facilities and only up to 3000mm of height. So DPI Japan complaint is now QUANTIFIED rather than rhetorical, and batch 10 reading of REF-00993 does not need narrowing; it needed this document to be measurable. SECOND FINDING, NOT PREDICTED: 1:20 is exactly AD M (REF-00992) limit for a 10 m flight. Two bodies with no shared lineage, one a building regulator and one a sports federation, land on the same number for a full-length ramp. That is what convergence looks like when it is real, and it stands against the three-way 1:12 agreement batch 10 showed to be an artefact of reading differently-shaped rules as one figure. THIRD: it states NO basis — across 216 pages, ZERO occurrences of ISO, zero of evidence, and no named reference standard, so it asserts exactly as the codes do. FOURTH: it defines a ramp as usually having a running slope greater than 1:20 (p.24), so below that it is a pathway — a definitional boundary no other source in this corpus states. RICHNESS NOW CLEARS on >=1 T4 international, and the determination is deliberately NOT recomputed (priors refusal 3): clearing richness is mechanical and is not an answer to the owner question.', 0, 'Named by REF-00993 as the benchmark. Prediction: it is freely published (the IPC distributes it for host cities), it states a ramp gradient, and that gradient is SHALLOWER than 1:12 — which is what would make DPI Japan "the mandatory standard is low" concrete rather than rhetorical. Falsified if it restates 1:12, in which case the Co-1 complaint is about scope and enforcement rather than about the gradient figure, and batch 10 reading of REF-00993 needs narrowing.');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation") VALUES (50, 'accessible-circulation-geometry', 'JP', 'ja', 4, 'standard_eb', 'international', 'JIS T 9251 規格票 傾斜 勾配 日本産業標準調査会 JISC 閲覧', NULL, 'web', 'scoping', NULL, 9, 18, 0, NULL, NULL, NULL, 0, 'session_2026-09-17-research-batch-11-threshold-legs-bcd', '2026-09-17 21:41', 'PRIOR CONFIRMED; LEAD 84 IS WRONG ON ITS JIS ENTRY, AND THE UNVERIFIED RECOLLECTION IS NOW VERIFIED AGAINST THE STANDARDS BODY OWN CARRIER. JIS T 9251:2014 is 高齢者・障害者配慮設計指針－視覚障害者誘導用ブロック等の突起の形状・寸法及びその配列 — the design guideline for the SHAPES, DIMENSIONS AND PATTERNS OF RAISED PARTS OF TACTILE WALKING SURFACE INDICATORS for blind and partially sighted people. It is the tactile paving standard. Evidence: the official JSA preview PDF (webdesk.jsa.or.jp, HTTP 200, 688,964 bytes, persisted as 024a7f1a8221788c.pdf) carries the full title, the 平成26年5月20日 revision date, and the drafting committee; across its five pages 傾斜 occurs 0 times, 勾配 0 times, スロープ 0 times. NOTHING ADMITTED — this standard is not evidence about ramp gradient and filing it here would be the containerising error the item-layer deletion was meant to stop. R14 ON THE ROUTE, SEPARATELY: JISC direct URLs are session-gated and returned システムエラー (HTTP 200 carrying an error body, persisted) — RETRIEVAL FAILURE for JISC, but not for the question, which the JSA preview answered outright. THE CORRECTION CANNOT BE WRITTEN TO THE LEAD: there is no update-code-lead verb (GAP-005, raised by batch 10 for this exact class), add-code-lead refuses a restatement of one standard per parameter, and lead 84 therefore keeps telling the next reader that a tactile-paving standard carries a ramp gradient. Recorded here and in the batch record until the writer exists.', 0, 'Lead 84 names JIS T 9251:2014 against ramp gradient. I DOUBT THE LEAD, AND THE DOUBT IS THE REASON TO RUN THE ROW. My recollection is that T 9251 is the tactile ground surface indicator standard rather than a ramp standard — [UNVERIFIED], memory, and exactly the kind of claim this project does not act on unread. JISC offers free browsing, so it is testable rather than arguable. Prediction: the standard is retrievable AND is about a different parameter, which makes this row a CORRECTION to lead 84 rather than an admission. R15 governs.');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation") VALUES (51, 'accessible-circulation-geometry', 'BE', 'nl', 6, 'code', 'intrinsic', 'Stedenbouwkundige verordening toegankelijkheid Vlaanderen artikel 19 helling hellingspercentage gepubliceerde tekst', NULL, 'web', 'scoping', NULL, 9, 9, 1, NULL, NULL, NULL, 0, 'session_2026-09-17-research-batch-11-threshold-legs-bcd', '2026-09-17 21:44', 'PRIOR CONFIRMED ON BOTH CLAUSES. Retrieved from Codex Vlaanderen, HTTP 200, 175,309 bytes persisted. The decree is dated 5 juni 2009 and the article carries its own in-force marker (31/03/2011), so candidate 69 now has the dated carrier it asked for and is resolved ADMITTED against REF-00995. TABLE CONFIRMED band for band: 10% to 10cm, 8,3% for 10-25cm, 6,25% for 25-50cm, 5% for 50cm or greater. CRITERION ABSENT, as predicted: fysieke haalbaarheid occurs ZERO times in the bytes, so the acceptability criterion is the Handboek commentary and still needs its own carrier — it remains the one statement in this corpus framed on what a wheelchair user can actually do, and it is now the highest-value single target left. TWO FINDINGS BEYOND THE PRIOR. (1) A THIRD RULE SHAPE: Flanders conditions on the RISE bridged, and the decree own memorandum says this was a deliberate break — een volledig ander vertrekpunt dan in het koninklijk besluit van 1977, dat maximale hellingspercentages vastlegde in functie van de LENGTE. With GB conditioned on the GOING and US/JP flat, no two of the three shapes are numerically comparable. (2) THE OFFICIAL DOCUMENT CONTRADICTS ITSELF: its explanatory memorandum lists FIVE bands including 7% for 25-35cm; the normative article has FOUR and merges 25-50cm at 6,25%. A researcher reading the toelichting — which sits in the same official page, above the article — would file a 7% band that is not in force. That is the same second-hand-attribution shape as the REF-00989 error batch 10 found, this time inside one government document. THE CONVERGENCE THAT IS REAL: 5% here equals IPC best practice and AD M 10 m limit, three bodies with no shared lineage.', 0, 'THE ROUTE IS THE CANDIDATE OWN, NOT ONE I CHOSE. Candidate 69 names its resolution explicitly: resolve by retrieving a dated carrier (the Flemish Stedenbouwkundige verordening toegankelijkheid Art. 19 as published). That is a dated Flemish decree, published free, and it carries the gradient table in a form that can be given a --year. Prediction: Art. 19 states the rise-conditioned table and does NOT carry the acceptability criterion, which is the handbook own commentary — so the decree resolves the table and leaves the criterion still needing its own dated carrier. R15: re-describe from the decree, and correct the candidate if the table differs.');
INSERT INTO "evidence_population_match" ("match_id", "source_ref", "target_population", "study_population", "sample_size", "match_grade", "mismatch_note", "created_at", "created_by_session", "ref_id", "gap_id") VALUES ('session_2026-09-17-resea-REF-00994-MOB', 'REF-00994', 'MOB', 'No study population — an international governing body stating design specifications for Games venues', NULL, 'PROXY', 'PROXY, on the same ground as every regulatory-stratum row in this cell (REF-00987 ADA is graded the same way): a standard asserts a figure, it does not study a population, so there is no population-of-study to compare against MOB. Two things make this row less of a pure proxy than a building code, and neither converts it to EXACT. The IPC is the governing body of Paralympic sport and its guide is written for venues whose users include a very high proportion of wheelchair users — so the population it designs for overlaps MOB more directly than a general building regulation does. And the guide scopes its own figures by facility importance rather than by user group. But it names no participants, reports no measurement, and states no evidence base anywhere in 216 pages, so grading it above PROXY would credit it with a warrant it does not claim.', '2026-09-17 21:45', 'session_2026-09-17-research-batch-11-threshold-legs-bcd', 'REF-00994', NULL);
INSERT INTO "evidence_population_match" ("match_id", "source_ref", "target_population", "study_population", "sample_size", "match_grade", "mismatch_note", "created_at", "created_by_session", "ref_id", "gap_id") VALUES ('session_2026-09-17-resea-REF-00995-MOB', 'REF-00995', 'MOB', 'No study population — a regional planning regulation stating gradient bands by rise', NULL, 'PROXY', 'PROXY, same ground as the other regulatory rows: a decree asserts, it does not study. Worth recording that the decree explanatory memorandum DOES give a user-facing warrant for one of its provisions — the intermediate landing exists so that a wheelchair user can turn back without completing the whole ramp — which is closer to a lived-experience rationale than anything the ADA, the Japanese order or AD M states for their figures. It is still the regulator asserting what wheelchair users need, not wheelchair users saying so, and the gradient bands themselves carry no warrant at all.', '2026-09-17 21:45', 'session_2026-09-17-research-batch-11-threshold-legs-bcd', 'REF-00995', NULL);
INSERT INTO "evidence_source_authors" ("id", "ref_id", "position", "last_name", "first_name", "suffix", "orcid", "is_corporate", "corporate_name", "corporate_name_en", "role", "created_at", "created_by_session", "corporate_name_note") VALUES (136, 'REF-00994', 1, NULL, NULL, NULL, NULL, 1, 'International Paralympic Committee', NULL, 'author', '2026-09-17 21:38', 'session_2026-09-17-research-batch-11-threshold-legs-bcd', NULL);
INSERT INTO "evidence_source_authors" ("id", "ref_id", "position", "last_name", "first_name", "suffix", "orcid", "is_corporate", "corporate_name", "corporate_name_en", "role", "created_at", "created_by_session", "corporate_name_note") VALUES (137, 'REF-00995', 1, NULL, NULL, NULL, NULL, 1, 'Vlaamse Regering (Flemish Government)', NULL, 'author', '2026-09-17 21:43', 'session_2026-09-17-research-batch-11-threshold-legs-bcd', NULL);
INSERT INTO "observed_terms" ("observation_id", "ref_id", "surface_form", "language", "locator", "context_quote", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (15, 'REF-00994', 'min. grade best practice', 'EN', 'Section 2.1, p.27', 'Ramps Slope 1:20 (5%) min. grade best practice', 'The IPC frames its governing figure as BEST PRACTICE rather than as a maximum, which is a different speech act from every code in this corpus. Harvested verbatim and unjudged (D-0173); whether best practice maps to our determination vocabulary is judgment work.', '2026-09-17 21:44', 'session_2026-09-17-research-batch-11-threshold-legs-bcd', '2026-09-17 21:44', 'session_2026-09-17-research-batch-11-threshold-legs-bcd');
INSERT INTO "observed_terms" ("observation_id", "ref_id", "surface_form", "language", "locator", "context_quote", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (16, 'REF-00994', 'secondary or ancillary facilities', 'EN', 'Section 2.1, p.27 comments', '1:14 (7.14%) max. grade is acceptable for secondary or ancillary facilities.', 'The IPC scopes its RELAXED figure by facility importance, not by rise or run. A fourth conditioning variable, distinct from the Japanese rise-condition and the UK going-condition.', '2026-09-17 21:44', 'session_2026-09-17-research-batch-11-threshold-legs-bcd', '2026-09-17 21:44', 'session_2026-09-17-research-batch-11-threshold-legs-bcd');
INSERT INTO "observed_terms" ("observation_id", "ref_id", "surface_form", "language", "locator", "context_quote", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (17, 'REF-00995', 'hellingspercentage', 'NL', 'Artikel 19 §1', 'Het hellingspercentage bedraagt hoogstens : 1° tien procent bij niveauverschillen tot 10 cm', 'The Dutch-language statutory term for the gradient figure, expressed as a PERCENTAGE rather than a ratio. The corpus holds ratios (1:12, 1:20) and percentages (5%, 6%) as if interchangeable; they are the same quantity in different notations and the sources do not agree on which to use.', '2026-09-17 21:44', 'session_2026-09-17-research-batch-11-threshold-legs-bcd', '2026-09-17 21:44', 'session_2026-09-17-research-batch-11-threshold-legs-bcd');
INSERT INTO "observed_terms" ("observation_id", "ref_id", "surface_form", "language", "locator", "context_quote", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (18, 'REF-00995', 'niveauverschillen', 'NL', 'Artikel 19 §1', '1° tien procent bij niveauverschillen tot 10 cm, of in geval van buitenruimtes bij niveauverschillen van 2 tot en met 10 cm', 'The variable Flanders conditions on: the LEVEL DIFFERENCE bridged. Neither the Japanese nor the UK instrument conditions on this, and the decree own memorandum records the switch away from length as deliberate.', '2026-09-17 21:44', 'session_2026-09-17-research-batch-11-threshold-legs-bcd', '2026-09-17 21:44', 'session_2026-09-17-research-batch-11-threshold-legs-bcd');
INSERT INTO "observed_terms" ("observation_id", "ref_id", "surface_form", "language", "locator", "context_quote", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (19, 'REF-00995', 'tussenbordes', 'NL', 'Artikel 19 §2 en §4', 'Bij een overbrugging van een niveauverschil van meer dan 50 cm of een helling van meer dan 10 m met een hellingspercentage van meer dan vier procent, moet voor een tussenbordes van 120 cm op 150 cm gezorgd worden.', 'Intermediate landing. The memorandum gives its warrant in user terms — it lets a wheelchair user turn back without completing the whole ramp — which is the closest thing to a lived-experience rationale any code in this corpus states.', '2026-09-17 21:44', 'session_2026-09-17-research-batch-11-threshold-legs-bcd', '2026-09-17 21:44', 'session_2026-09-17-research-batch-11-threshold-legs-bcd');
INSERT INTO "search_admissions" ("exec_id", "ref_id", "created_at", "created_by_session") VALUES (49, 'REF-00994', '2026-09-17 21:39', 'session_2026-09-17-research-batch-11-threshold-legs-bcd');
INSERT INTO "search_admissions" ("exec_id", "ref_id", "created_at", "created_by_session") VALUES (51, 'REF-00995', '2026-09-17 21:44', 'session_2026-09-17-research-batch-11-threshold-legs-bcd');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at") VALUES (78, NULL, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'Accessible Home Design, 2nd Edition (Paralyzed Veterans of America)', NULL, 'UNVERIFIED', 1, 0, 'PVA substantive accessible-design guidance is in this sold publication, not on its free web surface, so nothing could be admitted from the three pages retrieved. Not purchased in this pass.', 'CO-1 AUTHORITY BEHIND A PAYWALL. PVA is a disabled-led membership organisation with on-staff architects — among the strongest Co-1 design authorities available on this parameter in English — and its guidance is a book. If it states a gradient, that is lived-experience authority attached to a number, which is what this cell most lacks. Worth an actual purchase decision rather than another retrieval attempt.', 'session_2026-09-17-research-batch-11-threshold-legs-bcd', '2026-09-17 21:35');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at") VALUES (79, NULL, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'Handboek Toegankelijkheid Publieke Gebouwen (Gelijke Kansen in Vlaanderen / Inter) — the acceptability criterion', NULL, 'UNVERIFIED', 3, 0, 'The criterion "Bij hellingen vormt de fysieke haalbaarheid van de (zelfstandige) rolstoelgebruiker het uitgangspunt" is NOT in the decree — fysieke haalbaarheid occurs zero times in the retrieved Codex bytes. It is the handbook own commentary and still needs its own dated carrier.', 'THE HIGHEST-VALUE SINGLE TARGET LEFT IN THIS CELL. Every figure this corpus holds is a ceiling asserted without warrant. This sentence is the only statement met so far that frames the threshold on what a wheelchair user can PHYSICALLY DO independently — which is the owner question of 2026-09-16, almost verbatim. Candidate 69 resolved the table half against REF-00995 and left this half open.', 'session_2026-09-17-research-batch-11-threshold-legs-bcd', '2026-09-17 21:45');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at") VALUES (80, NULL, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'ISO 21542:2021 Building construction — Accessibility and usability of the built environment', NULL, 'UNVERIFIED', 4, 0, 'Not retrieved this pass. ISO Online Browsing Platform publishes terms and scope free, full clauses sold; the gradient sits in the sold part.', 'Would be a SECOND T4 international standard. Richness already clears on REF-00994, so this is no longer needed to unlock the cell — it is worth retrieving for what it SAYS, specifically whether it converges on 1:20 like the IPC guide, AD M and the Flemish decree, or on 1:12 like the ADA and Japan. That is the question the corpus now actually has.', 'session_2026-09-17-research-batch-11-threshold-legs-bcd', '2026-09-17 21:45');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at") VALUES (81, NULL, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'Provinciale verordening West-Vlaanderen — toegankelijkheid, hellingspercentages', NULL, 'UNVERIFIED', 6, 0, 'Named inside REF-00995 own explanatory memorandum as applying the same norms EXCEPT the 7% band for rises of 25-35cm. Not retrieved.', 'Surfaced by reading the memorandum rather than by a query. Interesting because it is evidence about how a superseded band survived at provincial level, and because it is a rare case of one instrument in this corpus naming its disagreement with another explicitly.', 'session_2026-09-17-research-batch-11-threshold-legs-bcd', '2026-09-17 21:45');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at") VALUES (82, NULL, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'BS 8300-1:2018 / BS 8300-2:2018 — Design of an accessible and inclusive built environment', NULL, 'UNVERIFIED', 4, 0, 'Sold by BSI. Not retrieved. The BSI catalogue page is already held against seven ref_ids and is a landing page for a standards family, so meeting it again is not a new identity and must not be cross-filed as one.', 'AD M (REF-00992) lists BS 8300 in its standards references but attributes NO figure in Table 1 to it, so the citation chain is unproven in both directions. Its remaining value is testing that chain, not the number — AD M already gave the readable UK figure.', 'session_2026-09-17-research-batch-11-threshold-legs-bcd', '2026-09-17 21:45');
INSERT INTO "source_slug_links" ("ref_id", "slug", "local_ref_id", "created_at", "created_by_session", "updated_at", "updated_by_session", "relevance_note") VALUES ('REF-00994', 'accessible-circulation-geometry', '13', '2026-09-17 21:38', 'session_2026-09-17-research-batch-11-threshold-legs-bcd', '2026-09-17 21:38', 'session_2026-09-17-research-batch-11-threshold-legs-bcd', NULL);
INSERT INTO "source_slug_links" ("ref_id", "slug", "local_ref_id", "created_at", "created_by_session", "updated_at", "updated_by_session", "relevance_note") VALUES ('REF-00995', 'accessible-circulation-geometry', '14', '2026-09-17 21:43', 'session_2026-09-17-research-batch-11-threshold-legs-bcd', '2026-09-17 21:43', 'session_2026-09-17-research-batch-11-threshold-legs-bcd', NULL);
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (28, 'REF-00994', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'INT', NULL, 'numerical', '1:20', 'rise:run ratio', 'Ramps Slope 1:20 (5%) min. grade best practice 1:14 (7.14%) min. grade for height up to 3000mm 1:50 (2%) maximum cross slope', 'Section 2.1 Key Measurement Reference Table, p.27 (Pathways and circulation areas / Ramps)', NULL, 'committee_assertion', 'REF-00994', NULL, 'stated_unmeasured', 'not_device_scoped', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'verified', NULL, 'THE FIGURE THAT MAKES THE CO-1 COMPLAINT QUANTITATIVE. REF-00993 (DPI Japan) holds that Japan mandatory standard is LOW compared with the IPC Accessibility Guide. This is that guide, and the gap is now measurable rather than rhetorical: IPC best practice is 1:20 (5%) where the Japanese mandatory ceiling (REF-00990) and the ADA (REF-00987) both sit at 1:12 (8.33%) — a factor of 1.67 on the same parameter. The guide qualifies 1:20 as the MAX grade for ramps serving primary entrances, busy facilities, long or crowded walkways, or covering more than 3000mm of height; 1:14 (7.14%) is acceptable only for secondary or ancillary facilities. GENUINE CONVERGENCE, UNLIKE THE 1:12 CASE: 1:20 is exactly AD M (REF-00992) limit for a 10 m flight, reached by a different body for a different purpose — which is what convergence looks like when it is real, against the three-way false 1:12 agreement batch 10 took apart. IT STATES NO BASIS: across 216 pages the guide contains ZERO occurrences of ISO, zero of evidence, and names no reference standard, so relation=none is literal and root_type is committee_assertion. The guide also defines a ramp as usually having a running slope GREATER than 1:20 (p.24) — below that it is a pathway, not a ramp, which is a definitional boundary no other source in this corpus states. [VERBATIM-EXEMPT: The persisted artefact is a FlateDecode-compressed PDF (5,066,628 bytes, sha256 b1e81d4770d19d9b24b0bdd9e528a974d3c62142c31645191f79efb92e1780cf), so no substring of its rendered text occurs in its bytes. Read off p.27 of that exact artefact via pypdf and reproduced character for character, including the table''s run-together column order. The IPC publishes no HTML carrier of the Key Measurement Reference Table.]', '2026-09-17 21:38', 'session_2026-09-17-research-batch-11-threshold-legs-bcd', '2026-09-17 21:38', 'session_2026-09-17-research-batch-11-threshold-legs-bcd', 'claim', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (29, 'REF-00994', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'INT', NULL, 'numerical', '1:14', 'rise:run ratio', 'Ramps Slope 1:20 (5%) min. grade best practice 1:14 (7.14%) min. grade for height up to 3000mm 1:50 (2%) maximum cross slope', 'Section 2.1 Key Measurement Reference Table, p.27 — secondary/ancillary facilities', NULL, 'committee_assertion', 'REF-00994', NULL, 'stated_unmeasured', 'not_device_scoped', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'verified', NULL, 'THE IPC CONCESSION, AND IT IS STILL SHALLOWER THAN EVERY CODE IN THIS CORPUS. 1:14 (7.14%) is what the guide accepts for SECONDARY OR ANCILLARY facilities only, and for height up to 3000mm — not for primary entrances or busy routes, which stay at 1:20. Even this relaxed figure is shallower than the ADA and Japanese mandatory 1:12 (8.33%) and than the UK 1:12-at-2m, so the corpus now holds an international body treating as a grudging exception a gradient that three jurisdictions treat as their legal maximum. Filed figure_role=finding rather than condition, for the same mechanical reason as the AD M row: an extraction_relations edge needs --quote with no exemption, and a compressed PDF can carry none, so a condition here would qualify nothing and fail extraction_relations_integrity. finding keeps it out of gather_sources, which is correct — it is not the governing IPC figure. [VERBATIM-EXEMPT: Same persisted artefact and method as the sibling 1:20 extraction: FlateDecode-compressed PDF, sha256 b1e81d4770d19d9b24b0bdd9e528a974d3c62142c31645191f79efb92e1780cf, read via pypdf from p.27. One row of one table, filed separately because it states a different figure under a different condition.]', '2026-09-17 21:39', 'session_2026-09-17-research-batch-11-threshold-legs-bcd', '2026-09-17 21:39', 'session_2026-09-17-research-batch-11-threshold-legs-bcd', 'finding', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (30, 'REF-00995', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'BE', NULL, 'numerical', '5', '%', 'vijf procent bij niveauverschillen van 50 cm of groter', 'Artikel 19 §1, 4°', NULL, 'committee_assertion', 'REF-00995', NULL, 'stated_unmeasured', 'not_device_scoped', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'verified', NULL, 'A THIRD RULE SHAPE, AND THE THIRD INDEPENDENT ARRIVAL AT 5%. Flanders conditions gradient on the HEIGHT DIFFERENCE BRIDGED (niveauverschil), and the decree own explanatory memorandum says so in as many words: dit is een volledig ander vertrekpunt dan in het koninklijk besluit van 1977, dat maximale hellingspercentages vastlegde in functie van de LENGTE van de helling. So the corpus now holds three structurally different rules — US/JP a flat ceiling with no length or height term, GB conditioned on the GOING of a flight, BE-VL conditioned on the RISE — and they cannot be compared as bare numbers. Filed at 5% because that is the band for niveauverschillen van 50 cm of groter, i.e. any ramp of real height, and therefore the governing value. THAT FIGURE IS 1:20. It equals IPC best practice (REF-00994) and AD M limit for a 10 m flight (REF-00992), reached by a regional planning regulator, a sports federation and a building regulator with no shared lineage. Against that, the 8,3% band here applies only to rises of 10-25 cm — the same short-rise-buys-steeper structure as the Japanese 1:8 proviso. relation=none: the decree states the table on its own authority and names no reference for it.', '2026-09-17 21:43', 'session_2026-09-17-research-batch-11-threshold-legs-bcd', '2026-09-17 21:43', 'session_2026-09-17-research-batch-11-threshold-legs-bcd', 'claim', '<=');